sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    try {
        var instanceUrl = request.queryParams.instance_url;
         gs.info("🔍 testingggggggggeeeeeeeeeeee " + JSON.stringify(instanceUrl));

        if (!instanceUrl || instanceUrl.trim() === "") {
            gs.error("❌ Missing required parameter: instance_url");
            response.setStatus(400);
            response.setBody({ error: "Missing required parameter: instance_url" });
            return;
        }

		if (Array.isArray(instanceUrl)) {
            instanceUrl = instanceUrl[0]; // Convert string to array
			// gs.log('uuuuuuuuuuushdgfkjjbcd'+instanceUrl);
        }

        // Normalize input URL (trim whitespace)
        // instanceUrl = instanceUrl.trim();
        // gs.info("🔍 Step 1: Incoming API Request - Instance URL: [" + instanceUrl + "]");

        // 🔹 Step 2: Fetch System Property (`procurement.form`)
        var sysPropGr = new GlideRecord("sys_properties");
        sysPropGr.addQuery("name", "procurement.form");
        sysPropGr.query();

        if (!sysPropGr.next()) {
            gs.warn("❌ System Property 'procurement.form' does not exist.");
            response.setStatus(404);
            response.setBody({ error: "System property does not exist." });
            return;
        }

        gs.info("✅ Step 2: System Property 'procurement.form' Found");

        // 🔹 Step 3: Read and Trim Stored Data
        var propertyValue = sysPropGr.value.toString().trim();
        gs.info("📜 Step 3: Raw Property Value from System Property: " + propertyValue);

        var storedData = [];

        // 🔹 Step 4: Validate and Parse JSON Data
        if (!propertyValue || propertyValue === "null" || propertyValue === "undefined") {
            gs.warn("⚠️ Step 4: System property 'procurement.form' is empty or invalid.");
        } else {
            try {
                var parsedData = JSON.parse(propertyValue);
                gs.info("✅ Step 4: Successfully Parsed JSON Data");

                // 🔹 Convert object to array if needed
                if (Array.isArray(parsedData)) {
                    gs.info("🔄 Step 5: Data is already an array");
                    storedData = parsedData;
                } else if (typeof parsedData === "object") {
                    gs.info("🔄 Step 5: Converting single object to an array");
                    storedData = [parsedData]; // Wrap object inside an array
                } else {
                    gs.warn("⚠️ Step 5: Invalid data format in 'procurement.form'. Expected object or array.");
                    storedData = [];
                }
            } catch (error) {
                gs.error("❌ Step 4: Failed to parse system property data: " + error);
                storedData = [];
            }
        }

        // 🔹 Step 6: Debugging - Log Full Parsed Data
        gs.info("📦 Step 6: Parsed Data: " + JSON.stringify(storedData));

        // 🔹 Step 7: Filter Data by `instance_url`
        var filteredData = storedData.filter(item => {
            if (!item || !item.u_instance_url) {
                gs.warn("⚠️ Skipping record with missing `u_instance_url`: " + JSON.stringify(item));
                return false;
            }

            // var recordUrl = item.u_instance_url.trim(); // Normalize record URL

            var recordUrl = item.u_instance_url;

            // ✅ FIX: Extract string if it's an array
            if (Array.isArray(recordUrl) && recordUrl.length > 0) {
                recordUrl = recordUrl[0]; // Take the first URL from the array
            }
            var isMatch = recordUrl === instanceUrl; // Exact match check
			gs.log('tttttrrrrrrrrrrrrr'+JSON.stringify(recordUrl));
            gs.info("🔍 Checking Record: [" + recordUrl + "] vs Requested: [" + instanceUrl + "] - Match: " + isMatch);	
            return isMatch;
        });
		gs.log('length of recordd'+filteredData.length);
        // 🔹 Step 8: Log Filtering Results
        if (filteredData.length > 0) {
            gs.info("🎯 Step 8: Matched Records Found for instance_url: " + instanceUrl);
            gs.info("📦 Step 8: Filtered Response Data: " + JSON.stringify(filteredData));
            response.setStatus(200);
            response.setBody({ result: filteredData });
        } else {
            gs.warn("❌ Step 8: No matching record found for instance_url: " + instanceUrl);
            response.setStatus(204);
            response.setBody({ result: [] });
        }
    } catch (err) {
        gs.error("❌ Step 9: Server error: " + err.message);
        response.setStatus(500);
        response.setBody({ error: "❌ Server error: " + err.message });
    }
})(request, response);
















